      "title": "Fashion portrait + spatial typography",
      "url": "https://x.com/MrLarus/status/2102756484475990402",
      "public_url": "https://x.com/MrLarus/status/2102756484475990402",
      "source_posts": [
        "https://x.com/MrLarus/status/2102756484475990402",
        "https://x.com/MrLarus/status/2102756524850311387"
      ],
      "source_family": "Portraits & editorial",
      "subcategory": "Portrait/type interaction",
      "tags": [
        "portrait",
        "fashion",
        "photography",
        "typography"
      ],
      "attribution": "Larus Canus (@MrLarus)",
      "summary": "Portrait/type interaction. Original public reusable template and source examples. Exact per-image generation inputs are not established.",
      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "Prompt:\n\nCreate a 9:16 vertical high fashion editorial poster.\n\nTITLE: [insert title]\nSUBJECT: [describe the model, outfit, hairstyle and pose]\nCORE VISUAL DEVICE: [optical refraction / breaking through a physical frame / graphic overlay / giant typography environment / other spatial interaction]\nACCENT COLOR: [insert one main accent color]\nMOOD: [cold / elegant / experimental / cinematic / minimal]\n\nBuild the composition around the interaction between portrait photography and typography. The model should not simply stand beside the text. Make the typography physically participate in the image through overlap, masking, cropping, refraction, depth, foreground and background separation, or spatial interruption.\n\nUse one strong visual mechanism per poster and make it immediately readable at thumbnail size.\n\nCreate a clear editorial hierarchy:\n\n1. One oversized display title as the main graphic anchor\n2. The fashion portrait as the primary photographic subject\n3. A few meaningful editorial captions and credits\n4. One controlled graphic or physical intervention\n\nUse refined fashion typography, combining high contrast serif, condensed sans serif, modern grotesk, or subtle handwritten lettering. Large type can extend beyond the canvas and be partially hidden by the model. Small text should stay minimal, precise and meaningful rather than filling the page with random words.\n\nUse an asymmetric editorial grid, bold cropping, generous negative space and strong scale contrast. Allow the model, type and graphic elements to move between foreground, middle ground and background.\n\nKeep the palette restrained. Use mostly neutral tones such as ivory, soft gray, black or muted blue, with only one dominant accent color.\n\nThe portrait should feel like real fashion photography with natural skin texture, realistic fabric, believable hair and refined studio lighting. Avoid glossy CGI skin, excessive retouching and generic commercial modeling poses.\n\nThe final result should feel like an independent fashion magazine, experimental editorial campaign or art directed fashion poster, not a social media template.\n\nAvoid meaningless filler text, excessive decoration, numbered labels, Vol or Issue numbering, sparkle symbols, random logos, cluttered layouts, cheap gradients and repetitive poster formulas.",
      "copy_label": "Copy source prompt",
      "prompts": [
        {
          "text": "Prompt:\n\nCreate a 9:16 vertical high fashion editorial poster.\n\nTITLE: [insert title]\nSUBJECT: [describe the model, outfit, hairstyle and pose]\nCORE VISUAL DEVICE: [optical refraction / breaking through a physical frame / graphic overlay / giant typography environment / other spatial interaction]\nACCENT COLOR: [insert one main accent color]\nMOOD: [cold / elegant / experimental / cinematic / minimal]\n\nBuild the composition around the interaction between portrait photography and typography. The model should not simply stand beside the text. Make the typography physically participate in the image through overlap, masking, cropping, refraction, depth, foreground and background separation, or spatial interruption.\n\nUse one strong visual mechanism per poster and make it immediately readable at thumbnail size.\n\nCreate a clear editorial hierarchy:\n\n1. One oversized display title as the main graphic anchor\n2. The fashion portrait as the primary photographic subject\n3. A few meaningful editorial captions and credits\n4. One controlled graphic or physical intervention\n\nUse refined fashion typography, combining high contrast serif, condensed sans serif, modern grotesk, or subtle handwritten lettering. Large type can extend beyond the canvas and be partially hidden by the model. Small text should stay minimal, precise and meaningful rather than filling the page with random words.\n\nUse an asymmetric editorial grid, bold cropping, generous negative space and strong scale contrast. Allow the model, type and graphic elements to move between foreground, middle ground and background.\n\nKeep the palette restrained. Use mostly neutral tones such as ivory, soft gray, black or muted blue, with only one dominant accent color.\n\nThe portrait should feel like real fashion photography with natural skin texture, realistic fabric, believable hair and refined studio lighting. Avoid glossy CGI skin, excessive retouching and generic commercial modeling poses.\n\nThe final result should feel like an independent fashion magazine, experimental editorial campaign or art directed fashion poster, not a social media template.\n\nAvoid meaningless filler text, excessive decoration, numbered labels, Vol or Issue numbering, sparkle symbols, random logos, cluttered layouts, cheap gradients and repetitive poster formulas.",
          "source_url": "https://x.com/MrLarus/status/2102756524850311387",
          "role": "Original author template · verbatim source text"
        }
      ],
