      "title": "Slit-scan portraits · Vol.30",
      "url": "https://x.com/MrLarus/status/2097675015516758421",
      "public_url": "https://x.com/MrLarus/status/2097675015516758421",
      "source_posts": [
        "https://x.com/MrLarus/status/2097675015516758421",
        "https://x.com/MrLarus/status/2097675098400399520"
      ],
      "source_family": "Portraits & editorial",
      "subcategory": "Slit-scan optical portraits",
      "tags": [
        "portrait",
        "fashion",
        "photography",
        "typography",
        "slit-scan",
        "optical distortion"
      ],
      "attribution": "Larus Canus (@MrLarus)",
      "summary": "Slit-scan optical portraits. Original public reusable template and source examples. Exact per-image generation inputs are not established.",
      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "Prompt:\n\nTITLE: [your title]\nSUBJECT: [person + pose]\nDISTORTION: [echo / scan / motion delay / type refraction]\nPALETTE: [neutral base + one accent]\nFORMAT: 9:16\n\nCreate a premium fashion editorial portrait using controlled vertical slit-scan distortion.\n\nBegin with a strong realistic portrait and keep at least one clear identity anchor such as the eyes, profile or facial outline. Break selected areas into vertical slices with varied widths, compression and horizontal displacement, creating a gradual transition from clear photography to optical fragmentation.\n\nKeep some areas completely sharp rather than distorting the whole image. Preserve realistic skin, hair and fabric texture inside every slice.\n\nUse a restrained palette, strong silhouette and generous negative space. Keep typography clean and editorial: one title, one short phrase and minimal supporting copy.\n\nThe result should feel like an optical photography experiment and high-fashion magazine poster, not a digital glitch effect.\n\nAvoid RGB splitting, VHS noise, horizontal scanlines, uniform slices, neon cyberpunk graphics, excessive text, plastic skin, logos, numbering and watermarks.",
      "copy_label": "Copy source prompt",
      "prompts": [
        {
          "text": "Prompt:\n\nTITLE: [your title]\nSUBJECT: [person + pose]\nDISTORTION: [echo / scan / motion delay / type refraction]\nPALETTE: [neutral base + one accent]\nFORMAT: 9:16\n\nCreate a premium fashion editorial portrait using controlled vertical slit-scan distortion.\n\nBegin with a strong realistic portrait and keep at least one clear identity anchor such as the eyes, profile or facial outline. Break selected areas into vertical slices with varied widths, compression and horizontal displacement, creating a gradual transition from clear photography to optical fragmentation.\n\nKeep some areas completely sharp rather than distorting the whole image. Preserve realistic skin, hair and fabric texture inside every slice.\n\nUse a restrained palette, strong silhouette and generous negative space. Keep typography clean and editorial: one title, one short phrase and minimal supporting copy.\n\nThe result should feel like an optical photography experiment and high-fashion magazine poster, not a digital glitch effect.\n\nAvoid RGB splitting, VHS noise, horizontal scanlines, uniform slices, neon cyberpunk graphics, excessive text, plastic skin, logos, numbering and watermarks.",
          "source_url": "https://x.com/MrLarus/status/2097675098400399520",
          "role": "Original author template · verbatim source text"
        }
      ],
