      "copy_text": "Prompt:\n\nSport / activity: [ ]\nSubject: [adult man/woman, appearance and vibe]\nOutfit: [ ]\nMain action / pose: [ ]\nEnvironment: [ ]\nGear / equipment: [ ]\nHeadline: [ ]\nSubtitle: [ ]\nAccent color: [ ]\nAspect ratio: 9:16\n\nCreate a 9:16 full-body editorial sports portrait poster combining realistic photography with scrapbook-style collage design.\n\nMake the person the dominant visual, occupying around 75–85% of the poster height, with the full body and shoes visible. Use natural body proportions, realistic skin and hair, believable muscle tone, and a real sport-specific action rather than a stiff model pose.\n\nUse authentic training environments and natural or realistic studio lighting. Clothing, skin, equipment, hands, and body mechanics should look physically believable.\n\nCut the full person out with a clearly visible irregular white sticker / paper border.\n\nUse a clean off-white textured-paper background with a few torn-paper photos, tape, handwritten notes, arrows, and sport-specific details such as:\n\n equipment / gear\n movement or alignment details\n training environment\n route, rhythm, breathing, strength, or control notes\n\nKeep the collage secondary to the portrait.\n\nAdd a large handwritten headline “[Headline]” and clean subtitle “[Subtitle]”. Use [Accent color] for selected typography, arrows, underlines, tape, and small graphic accents.\n\nFinal style: realistic sports portrait + workout identity + editorial scrapbook poster.",
