      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "Prompt:\n\nCreate a 9:16 premium food advertising poster for a French pâtisserie brand.\n\nBrand: [BRAND NAME]\nDessert: [DESSERT NAME]\nHeadline: [MAIN TITLE]\nTagline: [3 SHORT ADJECTIVES]\nDescription: [ONE-SENTENCE PRODUCT DESCRIPTION]\nIngredients: [4 KEY INGREDIENTS]\nCraft details: [3 SHORT SELLING POINTS]\nBrand line: [SHORT BRAND SLOGAN]\nPalette: [MAIN COLORS]\nProps: [2–3 RELEVANT PROPS]\n\nUse a refined editorial layout with the branding and headline in the upper section, one hero dessert in the lower-middle section, and a small ingredient and craftsmanship panel near the bottom.\n\nPhotograph the dessert from a slightly elevated 35–45° angle. Keep the product realistic, appetizing, clearly structured, and visually dominant. Use natural side light, soft botanical or window shadows, warm textured plaster walls, stone or ceramic surfaces, and restrained styling.\n\nCombine elegant serif typography, a small handwritten accent, and clean sans-serif supporting text. Maintain generous negative space, clear hierarchy, accurate readable text, and a cohesive premium restaurant-brand aesthetic.\n\nUse one dominant product, 2–3 supporting props, low-saturation colors, realistic food textures, subtle film grain, natural depth of field, and polished commercial food photography.",
      "copy_label": "Copy source prompt",
      "prompts": [
        {
          "text": "Prompt:\n\nCreate a 9:16 premium food advertising poster for a French pâtisserie brand.\n\nBrand: [BRAND NAME]\nDessert: [DESSERT NAME]\nHeadline: [MAIN TITLE]\nTagline: [3 SHORT ADJECTIVES]\nDescription: [ONE-SENTENCE PRODUCT DESCRIPTION]\nIngredients: [4 KEY INGREDIENTS]\nCraft details: [3 SHORT SELLING POINTS]\nBrand line: [SHORT BRAND SLOGAN]\nPalette: [MAIN COLORS]\nProps: [2–3 RELEVANT PROPS]\n\nUse a refined editorial layout with the branding and headline in the upper section, one hero dessert in the lower-middle section, and a small ingredient and craftsmanship panel near the bottom.\n\nPhotograph the dessert from a slightly elevated 35–45° angle. Keep the product realistic, appetizing, clearly structured, and visually dominant. Use natural side light, soft botanical or window shadows, warm textured plaster walls, stone or ceramic surfaces, and restrained styling.\n\nCombine elegant serif typography, a small handwritten accent, and clean sans-serif supporting text. Maintain generous negative space, clear hierarchy, accurate readable text, and a cohesive premium restaurant-brand aesthetic.\n\nUse one dominant product, 2–3 supporting props, low-saturation colors, realistic food textures, subtle film grain, natural depth of field, and polished commercial food photography.",
          "source_url": "https://x.com/MrLarus/status/2084994928229138432",
          "role": "Original author template · verbatim source text"
        }
      ],
