      "attribution": "Larus Canus (@MrLarus)",
      "summary": "Transparent living spaces. Original public reusable template and source examples. Exact per-image generation inputs are not established.",
      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "【透明核心物体】：{玻璃杯 / 香水瓶 / 花瓶 / 玻璃球 / 其他透明容器}\n【空间功能】：{泳池 / 电梯 / 温室 / 地铁站 / 咖啡馆 / 阅读室等}\n【手绘人物】：{人物数量、身份、动作与穿搭}\n【内部元素】：{水 / 植物 / 家具 / 交通工具等}\n【主文案】：{一句简短、有画面感的中文短句}\n【画幅比例】：{默认 9:16}\n\n创作一张「摄影级透明玻璃 × 手绘微型人物」虚实结合创意海报。\n\n将【透明核心物体】放大到建筑或生活空间的尺度，并真正改造成【空间功能】。不要只是把小人放在物体旁边，而是让人物真实进入玻璃内部，并自然地使用这个空间。\n\n透明物体必须保持明显的摄影级真实质感，包括真实玻璃厚度、边缘高光、反射、透光、折射、焦散、投影，以及不同曲面造成的局部放大、压缩和视觉偏移。\n\n最重要的是让这些真实光学效果真正作用到手绘人物和内部空间上。例如人物经过玻璃观察时，腿部、身体或随身物品出现轻微折射变形；光线穿过玻璃后在地面、人物或内部设施上形成自然焦散，使人物真正存在于透明空间中，而不是简单贴在照片表面。\n\n【手绘人物】保持明显二维绘本语言：黑灰铅笔线稿、少量彩铅或轻水彩、简洁五官、修长成年人体比例。人物动作自然生活化，可以阅读、候车、游泳、喝咖啡、乘电梯或休息，不看镜头，不摆模特姿势。\n\n人物、家具、交通工具等内部元素可以保持手绘或轻半写实，而透明玻璃、水、植物等核心材质保持更强摄影感，形成“一半像真实摄影，一半像手绘绘本”的视觉碰撞。\n\n环境保持极简，大面积使用暖奶油白、浅米色纸张或干净生活空间作为背景，只保留与主题有关的少量元素。不要构建复杂房间、城市或商业场景。\n\n构图采用「巨大透明主体 + 微型人物 + 大留白」：\n\n核心玻璃物体占据主要视觉面积，人物相对较小，通过明显尺度反差增强视觉惊喜；缩略图状态下也应该能第一眼看懂“这个透明物体被改造成了什么空间”。\n\n在留白区域加入【主文案】，使用自然、不完全规整的中文手写字体，像日记、手账或独立绘本中的题字。可加入一句很小的英文旁注，但不要堆放大量文字。\n\n整体光线使用柔和自然光，充分表现透明材质的折射、反射、焦散和透光，同时保持画面清爽、温暖、有生活感和编辑海报感。\n\n最终效果应该让观众第一眼看到一个摄影质感很强的真实透明物体，第二眼才发现里面竟然生活着一群手绘小人，并进一步注意到玻璃折射、光影和人物之间真实的物理互动。",
      "copy_label": "Copy source prompt",
