      "copy_text": "【MAIN WORD】: {4–8 letter uppercase keyword}\n【CAMPAIGN TYPE】: {fashion / automotive / F&B / product launch}\n【BRAND / PRODUCT】: {name}\n【PHOTO SUBJECT】: {one complete commercial photographic scene}\n【BACKGROUND】: {color}\n【PALETTE】: {main colors}\n【TYPE STYLE】: {bold grotesk / geometric sans / serif}\n【TOP LEFT】: {date / launch info / venue}\n【TOP RIGHT】: {3 short concept words}\n【BOTTOM LEFT】: {product / material / feature info}\n【BOTTOM RIGHT】: {brand / campaign name}\n【FORMAT】: 9:16 vertical\n\nCreate a high-end commercial poster using **vertical sliced typography**.\n\nPlace 【MAIN WORD】 large at the center, occupying about 75–85% of the width. Keep the word bold, clearly readable and visually dominant.\n\nEmbed **one single continuous photograph** of 【PHOTO SUBJECT】 inside the entire word. The main subject — person, car, product, food or object — should remain recognizable, while major visual lines such as fabric, body lines, vehicle profiles, straps, reflections, steam or product edges continue naturally across the letters.\n\nKeep roughly the upper 40–45% of the letterforms intact. Extend selected lower strokes downward into 5–7 vertical sections with varied short, medium and long lengths. Let the lower slices carry secondary details, reflections, fabric, shadows or environment without breaking the main subject.\n\nContinue the same photograph through every slice. Use one strong continuous feature to visually connect the whole word.\n\nAdd a subtle soft shadow behind the typography, slightly offset to the lower right. Use a clean 【BACKGROUND】 with generous negative space and keep most visual complexity inside the letters.\n\nArrange supporting information around the composition:\n\nTop left: 【TOP LEFT】\nTop right: 【TOP RIGHT】\nBottom left: 【BOTTOM LEFT】\nBottom right: 【BOTTOM RIGHT】\n\nUse small, precise modern typography for secondary information. The final result should feel like a finished fashion campaign, automotive ad, food & beverage visual or product launch — not a template demonstration.",
