      "title": "Sculptural paper letterforms",
      "url": "https://x.com/MrLarus/status/2090066451851874405",
      "public_url": "https://x.com/MrLarus/status/2090066451851874405",
      "source_posts": [
        "https://x.com/MrLarus/status/2090066451851874405",
        "https://x.com/MrLarus/status/2090066617623294321"
      ],
      "source_family": "Typography",
      "subcategory": "Sculptural paper letterforms",
      "tags": [
        "paper sculpture",
        "material typography",
        "studio lighting"
      ],
      "attribution": "Larus Canus (@MrLarus)",
      "summary": "Sculptural paper letterforms. Original public reusable template and source examples. Exact per-image generation inputs are not established.",
      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "[LETTER]: {T / Y / P / E / any letter}\n[SPATIAL ACTION]: {fold / curve / intersect / layer / twist}\n[PAPER COLOR]: {ivory / muted blue / sage green / warm sand}\n[ACCENT COLOR]: {burgundy / cobalt blue / olive / ochre}\n[TITLE]: {e.g. P / CURVE}\n[FORMAT]: 9:16 vertical\n\nCreate an experimental editorial typography poster where a large, clearly recognizable letter is physically formed from real sheets of matte paper.\n\nKeep about 70–80% of the letter structure recognizable, then transform it through {SPATIAL ACTION}. Let the paper fold, curve, overlap, intersect, or move through different depths while preserving the essential anatomy of the letter.\n\nUse thin, flexible paper rather than thick 3D blocks. Show realistic paper edges, subtle surface texture, natural bends, soft tension, and convincing deformation.\n\nUse {PAPER COLOR} as the main paper tone with {ACCENT COLOR} appearing only where the structure changes — inside a fold, curve, intersection, cut edge, or deeper layer. Keep the palette muted and editorial, not brightly saturated.\n\nUse strong directional studio lighting to create large graphic shadows across the paper and background. Let light and shadow become part of the composition while keeping the paper form readable.\n\nKeep typography restrained. Use one medium-size title such as “{TITLE}”, one small series label, and only a minimal amount of micro text. Use modern Grotesk sans-serif typography with lighter weights, generous spacing, and soft charcoal or gray ink rather than heavy pure black.\n\nLeave large areas of paper completely free of text so the material, color, form, and shadow remain the main visual focus.\n\nBuild clear foreground, middle ground, and background relationships. Allow parts of the paper letter to extend beyond the frame for scale and tension.\n\nOverall aesthetic: experimental typography, Swiss editorial design, paper sculpture, modern graphic design, restrained color, high-end art direction, realistic studio photography.",
      "copy_label": "Copy source prompt",
      "prompts": [
        {
          "text": "[LETTER]: {T / Y / P / E / any letter}\n[SPATIAL ACTION]: {fold / curve / intersect / layer / twist}\n[PAPER COLOR]: {ivory / muted blue / sage green / warm sand}\n[ACCENT COLOR]: {burgundy / cobalt blue / olive / ochre}\n[TITLE]: {e.g. P / CURVE}\n[FORMAT]: 9:16 vertical\n\nCreate an experimental editorial typography poster where a large, clearly recognizable letter is physically formed from real sheets of matte paper.\n\nKeep about 70–80% of the letter structure recognizable, then transform it through {SPATIAL ACTION}. Let the paper fold, curve, overlap, intersect, or move through different depths while preserving the essential anatomy of the letter.\n\nUse thin, flexible paper rather than thick 3D blocks. Show realistic paper edges, subtle surface texture, natural bends, soft tension, and convincing deformation.\n\nUse {PAPER COLOR} as the main paper tone with {ACCENT COLOR} appearing only where the structure changes — inside a fold, curve, intersection, cut edge, or deeper layer. Keep the palette muted and editorial, not brightly saturated.\n\nUse strong directional studio lighting to create large graphic shadows across the paper and background. Let light and shadow become part of the composition while keeping the paper form readable.\n\nKeep typography restrained. Use one medium-size title such as “{TITLE}”, one small series label, and only a minimal amount of micro text. Use modern Grotesk sans-serif typography with lighter weights, generous spacing, and soft charcoal or gray ink rather than heavy pure black.\n\nLeave large areas of paper completely free of text so the material, color, form, and shadow remain the main visual focus.\n\nBuild clear foreground, middle ground, and background relationships. Allow parts of the paper letter to extend beyond the frame for scale and tension.\n\nOverall aesthetic: experimental typography, Swiss editorial design, paper sculpture, modern graphic design, restrained color, high-end art direction, realistic studio photography.",
          "source_url": "https://x.com/MrLarus/status/2090066617623294321",
          "role": "Original author template · verbatim source text"
        }
      ],
