      "summary": "Material adventures. Original public reusable template and source examples. Exact per-image generation inputs are not established.",
      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "【核心真实材质】：{颜料 / 水花 / 肥皂泡 / 蜂蜜 / 咖啡 / 巧克力等}\n【视觉创意】：{材质形成的超现实场景或结构}\n【人物动作】：{滑行 / 冲浪 / 漂浮 / 划船 / 攀爬等}\n【物理互动】：{飞溅 / 挤压 / 折射 / 漂浮 / 拉丝 / 流动等}\n【主标题】：{一句简短有趣的英文短句}\n【英文副文案】：{一句与画面相关的简短英文}\n【主色调】：{根据真实材质选择}\n【画幅比例】：9:16\n\n创作一张「TINY FLOW」系列的摄影质感 × 手绘线稿混合视觉创意海报。\n\n将【核心真实材质】放大到超现实尺度，让它自然形成【视觉创意】所描述的场景。一位微型手绘成年人物正在其中进行【人物动作】，让真实物质成为可以探索、使用或互动的奇妙世界。\n\n真实材质表现：\n\n核心物体采用高度写实的微距摄影质感，准确呈现对应材质的纹理、厚度、光泽、透光、反射和物理特性。液体应具有真实的重力、黏度、表面张力与流动方向；泡泡应呈现自然虹彩薄膜和光学反射；浓稠物质需要保留真实拉丝、堆积和缓慢形变。主体必须具有清晰、完整的大形，避免塑料、CGI、抽象雕塑或不合理的魔法效果。\n\n手绘人物表现：\n\n人物采用自然修长的成年人比例，黑灰铅笔线稿、彩铅局部填色、轻微蜡笔纹理和简洁灵动的五官。穿着米白色休闲上衣、浅蓝牛仔服装、白色运动鞋，搭配少量芥末黄色配饰。深棕色头发自然蓬松，动作轻松、有趣，具有真实的运动姿态。人物必须明显是手绘角色，不要生成真人摄影皮肤、3D 卡通或动漫人物。\n\n物理融合与互动：\n\n人物与真实物质之间必须产生明确的【物理互动】。根据动作表现真实的接触、遮挡、受力、反射、压痕、飞溅、流动扰动或液体形变，让手绘人物真正存在于真实物质的空间中。人物动作、重心、道具和物体的运动方向应符合物理逻辑，避免简单贴图、悬浮或没有接触关系的拼贴效果。\n\n构图与排版：\n\n采用「巨大真实主体 + 微型手绘人物 + 大面积留白」的编辑海报构图。核心真实材质占据主要视觉区域，通过圆形、S 形、C 形、流动曲线或其他鲜明轮廓形成强烈视觉锚点。背景使用干净温润的奶油白纸张，保留极轻微天然纸纤维。环境元素尽量简化，不要加入无关道具。\n\n画面上方或左上方加入英文手写主标题：【主标题】\n\n下方以较小的自然手写字体加入：【英文副文案】\n\n文字采用深海军蓝或近黑色，笔触略有不规则，搭配少量中性手绘曲线作为辅助装饰。所有可见文字必须为英文，拼写准确，不出现中文、编号、Logo 或无意义文字。\n\n光线与色彩：\n\n使用明亮、柔和、具有真实方向性的摄影级自然光。核心材质保持【主色调】的鲜明色彩，充分表现真实高光、阴影、透光和纹理层次。人物、道具与真实物质共享一致的光线方向、透视与空间关系。整体色彩克制，以一个鲜明主色为视觉焦点，搭配奶油白背景、深蓝文字及少量低饱和辅助色。\n\n最终效果：\n\n画面同时具有真实物质的摄影级细节、手绘人物的温度、超现实尺度的趣味和国际化编辑海报的设计感。\n\n第一眼被巨大真实材质的颜色、形态和光影吸引，第二眼发现手绘小人物正在与它发生意想不到但可信的物理互动。即使不阅读文字，也能理解画面中的视觉创意。\n\n避免：纯摄影、纯插画、3D 卡通人物、CGI 塑料材质、生硬拼贴、人物悬浮、错误物理关系、复杂背景、过度装饰、大量随机液滴、无意义英文、中文文字和信息过载。",
      "copy_label": "Copy source prompt",
