      "title": "Scene-integrated big type",
      "url": "https://x.com/MrLarus/status/2090320559389192446",
      "public_url": "https://x.com/MrLarus/status/2090320559389192446",
      "source_posts": [
        "https://x.com/MrLarus/status/2090320559389192446",
        "https://x.com/MrLarus/status/2090320792626266179"
      ],
      "source_family": "Typography",
      "subcategory": "Scene-integrated typography",
      "tags": [
        "photography",
        "architecture",
        "cultural editorial"
      ],
      "attribution": "Larus Canus (@MrLarus)",
      "summary": "Scene-integrated typography. Original public reusable template and source examples. Exact per-image generation inputs are not established.",
      "status": "Public author template recovered",
      "copy_kind": "full_source_prompt",
      "copy_text": "Prompt:\n\n[SUBJECT]: {person / architecture / everyday object / lifestyle scene}\n[TITLE]: {one short keyword}\n[THEME]: {what the image represents}\n[SCENE]: {city / field / street corner / architectural space}\n[ACCENT COLOR]: {red / blue / orange / etc.}\n[SHORT LINE]: {one meaningful sentence}\n[FORMAT]: 9:16\n\nCreate an experimental editorial poster combining photography, oversized typography, and subtle print texture.\n\nUse {SUBJECT} as the main visual inside {SCENE}. Keep it realistic, distinctive, and large enough to hold the composition. The subject should feel like a real cultural or everyday observation, not a generic stock image.\n\nSet {TITLE} in oversized bold condensed sans-serif type. Do not simply place the title over the image — let the subject and typography overlap, interrupt, frame, or pass behind each other so they become one composition. The typography can respond naturally to the subject’s shape, direction, or architecture.\n\nUse a warm off-white, concrete gray, or deep charcoal base with subtle paper grain and slightly aged print texture. Keep most of the palette neutral and use {ACCENT COLOR} only in a few small lines, blocks, or graphic marks.\n\nAdd restrained editorial details such as thin guide lines, diagrams, maps, grids, annotations, or geometric elements only when they support the subject. Keep the layout rich but controlled, with clear hierarchy and intentional negative space.\n\nKeep all supporting text meaningful and minimal. Avoid random placeholder words, excessive technical data, unnecessary numbering, logos, watermarks, sparkles, and decorative clutter.\n\nOverall style: contemporary editorial design × photographic collage × experimental typography × subtle neo-retro print aesthetics.",
      "copy_label": "Copy source prompt",
      "prompts": [
        {
          "text": "Prompt:\n\n[SUBJECT]: {person / architecture / everyday object / lifestyle scene}\n[TITLE]: {one short keyword}\n[THEME]: {what the image represents}\n[SCENE]: {city / field / street corner / architectural space}\n[ACCENT COLOR]: {red / blue / orange / etc.}\n[SHORT LINE]: {one meaningful sentence}\n[FORMAT]: 9:16\n\nCreate an experimental editorial poster combining photography, oversized typography, and subtle print texture.\n\nUse {SUBJECT} as the main visual inside {SCENE}. Keep it realistic, distinctive, and large enough to hold the composition. The subject should feel like a real cultural or everyday observation, not a generic stock image.\n\nSet {TITLE} in oversized bold condensed sans-serif type. Do not simply place the title over the image — let the subject and typography overlap, interrupt, frame, or pass behind each other so they become one composition. The typography can respond naturally to the subject’s shape, direction, or architecture.\n\nUse a warm off-white, concrete gray, or deep charcoal base with subtle paper grain and slightly aged print texture. Keep most of the palette neutral and use {ACCENT COLOR} only in a few small lines, blocks, or graphic marks.\n\nAdd restrained editorial details such as thin guide lines, diagrams, maps, grids, annotations, or geometric elements only when they support the subject. Keep the layout rich but controlled, with clear hierarchy and intentional negative space.\n\nKeep all supporting text meaningful and minimal. Avoid random placeholder words, excessive technical data, unnecessary numbering, logos, watermarks, sparkles, and decorative clutter.\n\nOverall style: contemporary editorial design × photographic collage × experimental typography × subtle neo-retro print aesthetics.",
          "source_url": "https://x.com/MrLarus/status/2090320792626266179",
          "role": "Original author template · verbatim source text"
        }
      ],
