      "copy_kind": "full_source_prompt",
      "copy_text": "A professional educational infographic for a [Subject], designed in a modern \"Terrestrial Life\" series style. The layout features a large, realistic 3D central illustration of the [Subject] with anatomical labels like \"Compound Eyes,\" \"Thorax,\" and \"Abdomen\" using thin pointer lines. The color palette is clean with soft beige and muted tones. The composition includes multiple data modules: a \"Quick Profile\" sidebar, a \"Top 5 Amazing Facts\" list, a \"Size Comparison\" chart against a human silhouette, and a \"Knowledge Score\" star rating system. Include a \"Detail Focus\" section on the right with four square macro-photography close-ups of life stages or specific features. The bottom features \"Habitat\" and \"Diet\" icons, a \"Conservation Status\" slider, and a small \"Did You Know?\" footer. High resolution, crisp typography, clean vector lines, and a professional scientific journal aesthetic.",
