      "content_note": "Full public author template; requires uploaded source photo; exact per-image input provenance unverified Original top / filtered bottom comparisons. Source 2 visually inspected: coastal couple retained photographically in voxel scenery. Requires an input photo. Original Minecraft prompt is unchanged. Any LEGO adaptation must be separately labeled as an assistant adaptation and must not be presented as the original author prompt or as an existing generated example. Source text is preserved verbatim. Examples remain credited to their respective authors; public availability is not a blanket reuse license.",
