          "text": "Use the uploaded photograph as the source. Preserve every real person exactly: identity, face, expression, hair, clothing, anatomy, pose and placement. Preserve the original camera view, crop and spatial relationships. Change only the environment into a LEGO-style brick-built world with visible studs, layered plates, stepped slopes and convincing interlocking construction. Rebuild trees, paths, rocks, buildings and water as detailed molded-plastic assemblies. Keep people photographic, not minifigures. Match light direction, color temperature, perspective, reflections and contact shadows so the real subject sits naturally in the constructed scene. Use brick-built foliage and terrain rather than generic Minecraft voxel cubes. Do not add logos, watermarks, extra people or text. Output at the original aspect ratio.",
