      "source_family": "Editorial collage",
      "copy_kind": "user_supplied_source_prompt",
      "copy_text": "Create a 9:16 editorial collage poster built around a fan-shaped composition where the geometry directly expresses the concept.\n\nSUBJECT: [your theme / subject]\nTITLE: [main title]\nCONCEPT: [what the poster should communicate]\nFAN STRUCTURE: [layered curved fan / concentric arcs / large color wedges / radial burst / custom variation]\nVISUAL CONTENT: [people / places / events / objects / moments / textures]\nCOLOR SYSTEM: [2–5 dominant colors]\nTYPOGRAPHY: [editorial serif / grotesk / condensed sans / mixed system]\nBACKGROUND: [paper tone / flat color / minimal backdrop]\nTEXT DETAILS: [short meaningful phrases / optional event or editorial information]\n\nChoose the fan structure according to the meaning of the poster rather than using it as decoration.\n\nFor example:\n\n* layered curved fans can suggest distance, travel, space, or unfolding experience\n* concentric arcs can suggest emotion, perception, memory, or inner states\n* large color wedges can organize communities, events, contrasting themes, or parallel worlds\n* sharp radial cuts can suggest time, speed, simultaneous moments, or explosive energy\n\nBuild one clear large-scale composition first. From a distance, the fan geometry should be immediately readable and visually striking; up close, the viewer should discover richer photography, people, environments, textures, and narrative details.\n\nDo not make every section equal. Vary the width, scale, density, and direction of the fan areas. Mix image-heavy sections with pure color fields and negative space to create rhythm.\n\nPhotography should adapt to the geometry rather than sit inside rectangular frames. Use bold cropping, scale shifts, partial subjects, layered imagery, and a few controlled elements crossing the boundaries when useful.\n\nKeep each major section visually coherent with its own dominant color or tonal identity. The overall palette should feel intentional, not randomly multicolored.\n\nTypography should support the concept and composition. Use one strong title, a concise supporting line, and only the amount of editorial information the poster actually needs. Place text mainly in quieter areas so it does not compete with the most complex collage regions.\n\nThe finished image should feel like a complete art or editorial poster, not a fan-shaped photo template. The shape itself should help tell the story.",
      "copy_label": "Copy source prompt",
      "content_note": "Verbatim source text pasted by you, with two distinct variants in this shared style family. The exact source-post mapping and any adapted archive-generation wording remain unverified.",
      "new_source_style": true,
      "public_url": "https://www.meigen.ai/prompt/2095845240221368708",
      "attribution": "Larus Canus / @MrLarus",
      "source_text_located": true,
      "prompt_variants": [
        {
          "id": "fan-1",
          "title": "Concept-driven fan geometry",
          "text": "Create a 9:16 editorial collage poster built around a fan-shaped composition where the geometry directly expresses the concept.\n\nSUBJECT: [your theme / subject]\nTITLE: [main title]\nCONCEPT: [what the poster should communicate]\nFAN STRUCTURE: [layered curved fan / concentric arcs / large color wedges / radial burst / custom variation]\nVISUAL CONTENT: [people / places / events / objects / moments / textures]\nCOLOR SYSTEM: [2–5 dominant colors]\nTYPOGRAPHY: [editorial serif / grotesk / condensed sans / mixed system]\nBACKGROUND: [paper tone / flat color / minimal backdrop]\nTEXT DETAILS: [short meaningful phrases / optional event or editorial information]\n\nChoose the fan structure according to the meaning of the poster rather than using it as decoration.\n\nFor example:\n\n* layered curved fans can suggest distance, travel, space, or unfolding experience\n* concentric arcs can suggest emotion, perception, memory, or inner states\n* large color wedges can organize communities, events, contrasting themes, or parallel worlds\n* sharp radial cuts can suggest time, speed, simultaneous moments, or explosive energy\n\nBuild one clear large-scale composition first. From a distance, the fan geometry should be immediately readable and visually striking; up close, the viewer should discover richer photography, people, environments, textures, and narrative details.\n\nDo not make every section equal. Vary the width, scale, density, and direction of the fan areas. Mix image-heavy sections with pure color fields and negative space to create rhythm.\n\nPhotography should adapt to the geometry rather than sit inside rectangular frames. Use bold cropping, scale shifts, partial subjects, layered imagery, and a few controlled elements crossing the boundaries when useful.\n\nKeep each major section visually coherent with its own dominant color or tonal identity. The overall palette should feel intentional, not randomly multicolored.\n\nTypography should support the concept and composition. Use one strong title, a concise supporting line, and only the amount of editorial information the poster actually needs. Place text mainly in quieter areas so it does not compete with the most complex collage regions.\n\nThe finished image should feel like a complete art or editorial poster, not a fan-shaped photo template. The shape itself should help tell the story.",
          "source_kind": "user_supplied_source_prompt",
          "supplied_at": "2026-11-06T19:24:11.401900+00:00",
          "sha256": "daad0cdc58a8e4e36b03b1de1387fc1cc58887554dd18f0df7a19b9dd48ea3d2"
        },
        {
          "id": "fan-2",
          "title": "Flowing ribbons & motion",
          "text": "Create a 9:16 editorial poster based on a fan-shaped composition, with an emphasis on curved structures, flowing movement, and strong visual rhythm.\n\nSUBJECT: [your subject]\nTITLE: [main title]\nCONCEPT: [core idea or mood]\nFAN LOGIC: [flowing ribbon / offset arcs / radial burst / motion arcs / mixed curved fan structure]\nVISUAL MATERIALS: [photography / collage / textures / painting / architecture / people / objects]\nCOLOR SYSTEM: [2–4 main colors]\nTYPOGRAPHY: [serif / grotesk / condensed sans / editorial mix]\nBACKGROUND: [paper texture / flat tone / minimal backdrop]\nTEXT DETAILS: [optional short meaningful phrases]\n\nUse the fan-shaped composition as the main visual language, but do not limit it to straight wedges. The structure can bend, arc, curve, flow, expand, compress, or rotate depending on the concept.\n\nPrioritize graceful visual movement. Let the composition guide the eye through the poster with ribbons, arcs, layered curved sections, or a single radial burst used in a more expressive way.\n\nThe shape should help express the idea:\n\n* a flowing ribbon can suggest wind, motion, transition, or invisible force\n* offset arcs can suggest observation, rhythm, memory, or layered perception\n* a radial burst can suggest sound, signal, speed, or urban energy\n* motion arcs can suggest body movement, choreography, or time unfolding\n\nBuild a strong large silhouette first, then fill it with controlled visual variety. Mix image sections, pure color areas, negative space, and small editorial details so the poster feels designed rather than template-based.\n\nAllow some elements to break across the fan boundaries when useful. Curves should feel intentional and elegant, not decorative for their own sake.\n\nTypography should feel integrated into the composition. Use one clear title, a short supporting line, and a small amount of editorial text. Keep the copy meaningful and concise.\n\nThe final poster should feel like an art-forward editorial collage: visually striking from a distance, but richer and more layered up close.",
          "source_kind": "user_supplied_source_prompt",
          "supplied_at": "2026-11-06T19:24:11.401900+00:00",
          "sha256": "a6b0afbe256670ccebfc715f137fa6ca28acd6f4feac030509241e72d0e69d9b"
        }
      ]
